INSERT INTO [Store].[ProductDetail] ([DetailKey],[Intro],[HighlightsJson],[SpecsJson],[ReviewsJson],[QuestionsJson]) VALUES (N'group-1',N'دریل چکشی شارژی برای سوراخ‌کاری و نصب‌های روزمره طراحی شده است. طراحی بی‌سیم، جابه‌جایی بین محل کار و خانه را ساده می‌کند؛ پیش از خرید، ظرفیت باتری و سازگاری مته با سطح موردنظر را بررسی کنید.',N'["مناسب نصب و تعمیرات عمومی","قابلیت استفاده در محیط‌های بدون دسترسی مستقیم به برق","انتخاب مته متناسب با چوب، فلز یا مصالح"]',N'[["کاربری","سوراخ‌کاری و نصب"]]',N'[["کاربر مهمان","برای نصب قفسه و تعمیرات سبک ازش استفاده کردم؛ خوش‌دست بود و جابه‌جایی بین اتاق‌ها با باتری راحت‌تر شد.",5,"ممنون از اینکه تجربه‌تان را نوشتید. برای حفظ عملکرد دستگاه، از متهٔ مناسب سطح استفاده کنید و باتری را طبق راهنمای سازنده شارژ کنید."],["کاربر مهمان","برای سوراخ‌کاری چوب و فلز کارم را راه انداخت. کنترل سرعت کمک کرد شروع سوراخ‌کاری دقیق‌تر باشد.",4],["کاربر مهمان","قبل از خرید اندازهٔ سه‌نظام و نوع باتری را با مته‌هایی که داشتم تطبیق دادم؛ پیشنهاد می‌کنم اقلام داخل جعبه را هم بررسی کنید.",5],["کاربر مهمان","برای کارهای خانگی و نصب‌های معمولی انتخاب مناسبی است. در کار طولانی بهتر است بین کار به دستگاه استراحت بدهید.",4],["کاربر مهمان","وزن دستگاه برای نصب پرده و قفسه مناسب بود و کنترل دور هم کمک کرد پیچ‌ها را راحت‌تر ببندم.",5],["کاربر مهمان","برای کارهای سبک خانه خریدم. قبل از استفاده دفترچه را خواندم و متهٔ مناسب دیوار را جدا تهیه کردم.",4],["کاربر مهمان","سه‌نظام سریع باعث شد تعویض مته راحت باشد. برای سوراخ‌کاری‌های پشت‌سرهم، باتری اضافه کاربردی است.",5,"سپاس از تجربه‌تان. برای کار مداوم، ظرفیت باتری و زمان شارژ را با حجم کارتان هماهنگ کنید."],["کاربر مهمان","در کارگاه برای نصب‌های کوتاه استفاده کردم؛ دسته خوش‌دست است و نگهداری دستگاه هم ساده به نظر می‌رسد.",4],["کاربر مهمان","برای سوراخ‌کاری دقیق روی چوب، شروع آرام و ثابت نگه‌داشتن دستگاه نتیجهٔ خوبی داد.",5],["کاربر مهمان","پیش از سفارش ابعاد و اقلام همراه را بررسی کردم. پیشنهاد می‌کنم نوع باتری موردنیازتان را هم در مشخصات ببینید.",4],["کاربر مهمان","برای نصب کابینت و تعمیرات سبک مناسب است؛ برای کار سنگین‌تر بهتر است سراغ مدل متناسب با همان کاربرد بروید.",5],["کاربر مهمان","برای استفادهٔ خانگی انتخاب راحتی بود. بعد از هر بار کار، مته را جدا کردم و دستگاه را در جای خشک گذاشتم.",4]]',N'[["چه مته‌ای برای این دریل مناسب است؟","مته را با جنس سطح و قطر سوراخ انتخاب کنید و سازگاری آن با سه‌نظام دستگاه را بررسی کنید.",0,"برای چوب، فلز یا مصالح از متهٔ مخصوص همان سطح استفاده کنید و قطر قابل پشتیبانی سه‌نظام را در مشخصات مدل ببینید."],["باتری و شارژر داخل بسته هستند؟","اقلام همراه را در بخش مشخصات و فهرست محتویات بستهٔ همین کالا ببینید.",0,"محتویات بسته ممکن است بین نسخه‌های مختلف تفاوت داشته باشد؛ فهرست اقلام همین محصول را پیش از ثبت سفارش بررسی کنید."],["برای سوراخ‌کاری مصالح چه نکته‌ای مهم است؟","از متهٔ مناسب مصالح استفاده کنید و حالت چکشی و سرعت را مطابق راهنمای دستگاه تنظیم کنید.",0,"حالت چکشی را فقط برای مصالح مناسب فعال کنید و هنگام کار از عینک محافظ و فشار یکنواخت استفاده کنید."],["برای کارهای نصب خانگی مناسب است؟","برای نصب‌های متداول و تعمیرات عمومی کاربرد دارد؛ نوع کار و مدت استفاده را با مشخصات دستگاه تطبیق دهید.",0,"بله، برای کارهای معمول خانگی مناسب است. برای استفادهٔ پیوسته یا سنگین، ظرفیت باتری و محدودهٔ کاری دستگاه را در نظر بگیرید."],["چطور عمر باتری را بهتر حفظ کنم؟","شرایط شارژ و نگهداری اعلام‌شده از سوی سازنده را رعایت کنید.",0,"باتری را در دمای مناسب نگه دارید، از شارژر سازگار استفاده کنید و برای نگهداری طولانی‌مدت دستورالعمل سازنده را دنبال کنید."],["آیا می‌توان از این دستگاه برای بستن پیچ استفاده کرد؟","در صورت پشتیبانی دستگاه و استفاده از سری پیچ‌گوشتی سازگار، سرعت را متناسب با کار تنظیم کنید.",0,"برای جلوگیری از آسیب به پیچ یا سطح، از دور پایین شروع کنید و فشار را یکنواخت نگه دارید."],["سه‌نظام چه اندازه مته‌ای را می‌پذیرد؟","حداکثر قطر قابل پشتیبانی را در مشخصات فنی همین مدل بررسی کنید.",0,"اندازهٔ سه‌نظام بین مدل‌ها متفاوت است؛ پیش از خرید مته، محدودهٔ درج‌شده در مشخصات محصول را تطبیق دهید."],["برای استفادهٔ طولانی چه نکته‌ای را رعایت کنم؟","زمان کار پیوسته و محدودیت حرارتی دستگاه را مطابق دفترچهٔ راهنما رعایت کنید.",0,"در استفادهٔ سنگین به دستگاه استراحت دهید و از مسدود نبودن مسیر تهویه اطمینان پیدا کنید."],["آیا باتری دستگاه با ابزارهای دیگر سازگار است؟","سازگاری باتری را فقط بر اساس ولتاژ، سری و اعلام رسمی سازنده بررسی کنید.",0,"باتری‌های هم‌برند هم ممکن است بین سری‌ها سازگار نباشند؛ شماره مدل باتری و ابزار را مقایسه کنید."],["برای سوراخ‌کاری فلز از چه مته‌ای استفاده کنم؟","متهٔ مناسب فلز را انتخاب کنید و سرعت پیشنهادی سازندهٔ مته را رعایت کنید.",0,"قطعه را محکم کنید، از عینک محافظ استفاده کنید و برای قطرهای بزرگ‌تر، مرحله‌ای سوراخ‌کاری کنید."],["چطور از لغزش مته در شروع کار جلوگیری کنم؟","محل سوراخ را علامت بزنید و دستگاه را با سرعت کم و زاویهٔ درست شروع کنید.",0,"سطح کار را ثابت کنید و تا ایجاد شیار اولیه، دستگاه را بدون فشار ناگهانی کنترل کنید."],["آیا دستگاه برای کار روی بتن مناسب است؟","نوع مصالح و توانایی مدل را در مشخصات همین محصول بررسی کنید؛ همهٔ دریل‌ها برای بتن مناسب نیستند.",0,"برای بتن از مته و حالت مجاز همان دستگاه استفاده کنید و محدودیت کاربرد درج‌شده در دفترچه را رعایت کنید."],["چه زمانی باتری را شارژ کنم؟","چرخهٔ شارژ و نگهداری اعلام‌شده برای باتری همین مدل را دنبال کنید.",0,"از شارژر سازگار استفاده کنید و باتری را در معرض گرمای شدید یا رطوبت قرار ندهید."],["آیا کیف یا جعبه در بسته‌بندی وجود دارد؟","اقلام همراه هر نسخه ممکن است متفاوت باشد؛ فهرست بسته‌بندی را در مشخصات سفارش ببینید.",0,"برای اطمینان، محتویات درج‌شده برای همین محصول را پیش از نهایی‌کردن خرید بررسی کنید."]]'),(N'group-2',N'کیت مولتی‌متر دیجیتال برای اندازه‌گیری و عیب‌یابی اولیه در مدارهای الکتریکی به کار می‌رود. پیش از اندازه‌گیری، حالت مناسب را انتخاب کنید و ردهٔ ایمنی دستگاه را با محیط و ولتاژ کاری تطبیق دهید.',N'["مناسب بررسی اولیهٔ مدار","نمایش دیجیتال برای خواندن آسان‌تر مقدار","انتخاب رنج و ورودی مناسب پیش از اندازه‌گیری"]',N'[["کاربری","اندازه‌گیری و عیب‌یابی"],["نوع نمایش","دیجیتال"],["نکتهٔ ایمنی","بررسی ردهٔ حفاظتی پیش از استفاده"]]',N'[["کاربر مهمان","برای استفادهٔ کارگاهی، خوانایی نمایشگر و انتخاب درست حالت اندازه‌گیری اهمیت زیادی دارد.",5,"از دیدگاه شما سپاسگزاریم. برای اندازه‌گیری ایمن، حالت و ورودی دستگاه را متناسب با مدار انتخاب کنید و پیش از شروع، محدودهٔ کاری دستگاه را بررسی کنید."],["کاربر مهمان","پراب‌ها را قبل از استفاده بررسی کردم و برای کارهای عیب‌یابی روزمره انتخاب حالت دستگاه را ساده یافتم.",4],["کاربر مهمان","پیش از خرید، ردهٔ ایمنی و کمیت‌های قابل اندازه‌گیری را با نیازم تطبیق دادم؛ پیشنهاد می‌کنم مشخصات مدل را کامل بخوانید.",5],["کاربر مهمان","برای اندازه‌گیری‌های معمولی کارگاه مناسب بود. نگهداری پراب‌ها در کیف جداگانه کمک می‌کند آسیب نبینند.",4]]',N'[["پیش از اندازه‌گیری چه چیزی را بررسی کنم؟","حالت اندازه‌گیری، ورودی پراب و محدودهٔ کاری دستگاه را متناسب با مدار انتخاب کنید.",0,"پیش از اتصال پراب، سالم‌بودن عایق آن و انتخاب حالت و ورودی درست را بررسی کنید. برای کار روی مدار، ردهٔ ایمنی دستگاه باید با شرایط اندازه‌گیری سازگار باشد."],["این دستگاه چه کمیت‌هایی را اندازه می‌گیرد؟","قابلیت‌هایی مانند ولتاژ، جریان و مقاومت را از جدول مشخصات همین مدل بررسی کنید."],["چطور اندازه‌گیری ایمن‌تری داشته باشم؟","پراب سالم و ورودی درست را به کار ببرید و ردهٔ ایمنی دستگاه را با محیط کار تطبیق دهید."]]'),(N'group-3',N'ایستگاه هویه برای لحیم‌کاری قطعات و تعمیرات الکترونیکی طراحی شده است. کنترل دما و انتخاب نوک متناسب با قطعه، به کار دقیق‌تر کمک می‌کند؛ هنگام استفاده تهویهٔ مناسب و پایهٔ ایمن هویه را در نظر بگیرید.',N'["مناسب تعمیرات برد و لحیم‌کاری قطعات","امکان انتخاب نوک متناسب با نوع کار","توجه به کنترل دما و تهویهٔ محل کار"]',N'[["کاربری","لحیم‌کاری و تعمیرات الکترونیک"],["لوازم پیشنهادی","پایهٔ هویه، نوک یدکی و اسفنج تمیزکننده"]]',N'[["کاربر مهمان","برای مونتاژ قطعات ریز، انتخاب نوک مناسب و تنظیم دما نتیجهٔ کار را بهتر می‌کند.",5,"ممنون از اینکه تجربه‌تان را به اشتراک گذاشتید. نوک هویه را متناسب با ابعاد قطعه انتخاب کنید و برای لحیم‌کاری، تهویهٔ مناسب را در نظر داشته باشید."],["کاربر مهمان","کنترل دما برای تعمیرات برد کاربردی است. بهتر است قبل از شروع، زمان گرم‌شدن دستگاه را در نظر بگیرید.",4],["کاربر مهمان","برای کار دقیق، پایهٔ هویه و نوک متناسب با قطعه اهمیت زیادی دارد؛ اقلام داخل بسته را بررسی کنید.",5],["کاربر مهمان","در استفادهٔ روزمره عملکرد قابل قبولی داشت. تهویهٔ مناسب میز کار را فراموش نکنید.",4]]',N'[["چه نوکی برای لحیم‌کاری قطعات ریز مناسب است؟","نوک باریک و سازگار با هویه انتخاب کنید تا کنترل حرارت روی قطعات کوچک آسان‌تر باشد.",0,"نوک ظریف و سازگار با مدل ایستگاه، کنترل بهتری روی قطعات کوچک می‌دهد. پیش از خرید، سازگاری سری و توان دستگاه را در مشخصات بررسی کنید."],["دمای هویه را چطور تنظیم کنم؟","از دمای پیشنهادی قطعه و سیم لحیم شروع کنید و در صورت نیاز تنظیم را مرحله‌ای انجام دهید."],["برای کار با هویه چه نکته‌ای را رعایت کنم؟","از پایهٔ نسوز و تهویهٔ مناسب استفاده کنید و نوک داغ را پس از کار در جای ایمن قرار دهید."]]'),(N'group-4',N'چراغ کار LED برای روشن‌کردن فضای تعمیر، کارگاه یا محل نصب کاربرد دارد. هنگام انتخاب، شدت روشنایی، زاویهٔ تابش، نوع پایه و روش تأمین انرژی را متناسب با محیط استفاده بسنجید.',N'["مناسب روشنایی موضعی محیط کار","بررسی زاویهٔ تابش و امکان تنظیم پایه","انتخاب منبع تغذیه متناسب با محل استفاده"]',N'[["کاربری","روشنایی کارگاهی و تعمیراتی"],["نوع روشنایی","LED"],["نکتهٔ انتخاب","بررسی شار نوری و درجهٔ حفاظت"]]',N'[["کاربر مهمان","برای کار نزدیک، نور قابل تنظیم و پایهٔ پایدار استفاده را راحت‌تر می‌کند.",5,"از بازخورد شما سپاسگزاریم. برای انتخاب چراغ کار، زاویهٔ تابش و نوع پایه را با فضای کار خود هماهنگ کنید."],["کاربر مهمان","برای میز تعمیرات نور موضعی خوبی فراهم می‌کند. قبل از سفارش، نوع پایه و روش تغذیه را ببینید.",4],["کاربر مهمان","زاویهٔ تابش قابل تنظیم هنگام کار روی قطعات کوچک کمک‌کننده بود.",5],["کاربر مهمان","برای استفادهٔ کارگاهی مناسب است؛ محل قرارگیری چراغ را با فضای میز هماهنگ کنید.",4]]',N'[["چه چراغی برای میز کار مناسب است؟","زاویهٔ تابش، شدت نور و امکان تنظیم پایه را با ابعاد میز و نوع کار خود هماهنگ کنید.",0,"برای میز کار، نور یکنواخت و پایه یا زاویهٔ قابل تنظیم کاربردی است. شدت روشنایی و روش تأمین انرژی را با فضای کارتان تطبیق دهید."],["این چراغ با برق کار می‌کند یا باتری؟","روش تأمین انرژی و اقلام همراه را در مشخصات همین مدل ببینید."],["برای فضای مرطوب مناسب است؟","درجهٔ حفاظت درج‌شده برای مدل را بررسی کنید و از استفاده خارج از محدودهٔ اعلام‌شده بپرهیزید."]]'),(N'group-5',N'مجموعه ابزار برق‌کار برای انجام کارهای نصب و سرویس روزانه گردآوری می‌شود. محتویات بسته در مدل‌های مختلف فرق می‌کند؛ پیش از سفارش، فهرست اقلام و عایق‌بودن ابزارهای موردنیاز را با نوع کار تطبیق دهید.',N'["مناسب نصب و سرویس تجهیزات برقی","بررسی تعداد و نوع اقلام داخل بسته","انتخاب ابزار عایق متناسب با سطح ایمنی کار"]',N'[["کاربری","نصب و سرویس برق"],["نکتهٔ ایمنی","ابزار عایق جایگزین قطع برق و دستورالعمل ایمنی نیست"]]',N'[["کاربر مهمان","قبل از انتخاب، فهرست ابزارهای موردنیاز را با اقلام داخل جعبه تطبیق دهید.",5,"ممنون از نکتهٔ خوبی که گفتید. محتویات مجموعه را با نیاز کاری‌تان تطبیق دهید و برای کار برقی، ابزار مناسب و دستورالعمل ایمنی را رعایت کنید."],["کاربر مهمان","برای سرویس‌های معمولی مجموعهٔ کاربردی‌ای است. تعداد و نوع اقلام را با نیاز کارتان مقایسه کنید.",4],["کاربر مهمان","چیدمان ابزارها نگهداری را ساده می‌کند؛ مشخصات عایق‌بودن هر ابزار را جداگانه بررسی کنید.",5],["کاربر مهمان","برای کارهای نصب روزانه مناسب بود. بسته‌بندی را هنگام تحویل با فهرست اقلام تطبیق دادم.",4]]',N'[["داخل مجموعه چه ابزارهایی قرار دارد؟","فهرست دقیق محتویات بسته را در مشخصات همین کالا بررسی کنید؛ اقلام هر مجموعه متفاوت است.",0,"محتویات بین مدل‌ها و بسته‌بندی‌ها فرق می‌کند؛ فهرست اقلام درج‌شده برای همین کالا را پیش از سفارش ملاک قرار دهید."],["برای کار برق، ابزار عایق لازم است؟","ابزار را با سطح ایمنی و نوع کار انتخاب کنید و همیشه دستورالعمل‌های ایمنی را رعایت کنید."],["این مجموعه برای کارهای نصب مناسب است؟","اقلام داخل بسته را با ابزارهای موردنیاز برای نصب و سرویس خود تطبیق دهید."]]'),(N'group-6',N'تستر و فازمتر دیجیتال برای بررسی اولیهٔ وضعیت برق و تشخیص سریع در کارهای سرویس استفاده می‌شود. روش کار و سطح ایمنی ابزار را مطابق دستورالعمل سازنده رعایت کنید و برای تشخیص قطعی، از تجهیزات مناسب و فرد متخصص کمک بگیرید.',N'["مناسب بررسی اولیه و عیب‌یابی سریع","انتخاب قابلیت متناسب با نوع اندازه‌گیری","رعایت دستورالعمل ایمنی سازنده"]',N'[["کاربری","بررسی اولیهٔ مدار"],["نوع ابزار","تستر / فازمتر"],["نکتهٔ ایمنی","برای کار تخصصی از ابزار دارای ردهٔ ایمنی مناسب استفاده شود"]]',N'[["کاربر مهمان","برای استفادهٔ مطمئن، روش تست و محدودیت‌های ابزار را قبل از کار مطالعه کنید.",5,"از دیدگاه شما سپاسگزاریم. پیش از استفاده، راهنمای تست و محدودهٔ کاری ابزار را مرور کنید و نکات ایمنی سازنده را رعایت کنید."],["کاربر مهمان","برای بررسی‌های اولیه کار را سریع‌تر می‌کند؛ محدودهٔ ولتاژ را پیش از استفاده چک کنید.",4],["کاربر مهمان","راهنمای دستگاه را قبل از استفاده خواندم و ابزار را فقط در محدودهٔ درج‌شده به کار بردم.",5],["کاربر مهمان","برای سرویس‌های سبک انتخاب مناسبی بود. در کار تخصصی از تجهیزات دارای ردهٔ ایمنی مناسب استفاده کنید.",4]]',N'[["این تستر چه مواردی را تشخیص می‌دهد؟","نوع تشخیص و محدودهٔ کاری را در مشخصات همان مدل بررسی کنید؛ قابلیت‌ها بین مدل‌ها متفاوت است.",0,"قابلیت تشخیص به مدل بستگی دارد. محدودهٔ ولتاژ، نوع نشانگر و ردهٔ ایمنی را از مشخصات همین دستگاه بررسی کنید و خارج از محدودهٔ اعلام‌شده از آن استفاده نکنید."],["قبل از استفاده چه کاری انجام بدهم؟","روش تست، نشانگرها و محدودیت‌های ابزار را از راهنمای سازنده بخوانید."],["برای بررسی برق شهر قابل استفاده است؟","محدودهٔ ولتاژ و ردهٔ ایمنی مدل را پیش از استفاده بررسی کنید و نکات ایمنی را رعایت کنید."]]');
UPDATE p SET p.IdBrand=b.Id,p.IdCategory=c.Id,p.DetailKey=v.DetailKey,p.EnglishName=v.EnglishName,p.PowerSource=v.PowerSource,p.UseCase=v.UseCase,p.PriceAmount=CONVERT(DECIMAL(19,0),v.Price*1000000),p.DiscountPercent=v.DiscountPercent,p.MaxPurchaseQuantity=v.MaxPurchaseQuantity,p.Slug=v.Slug,p.Badge=v.Badge,p.IsNewest=v.IsNewest FROM [Store].[Product] p JOIN (VALUES (N'1',N'HN-001',N'bosch',N'hammer-drills',N'group-1',N'Cordless Hammer Drill',N'باتری شارژی',N'نصب و کارگاه',24.5,15,99,N'cordless-hammer-drill',N'پرفروش',1),(N'2',N'HN-002',N'makita',N'cordless-drill',N'group-1',N'Cordless Drill Driver',N'باتری شارژی',N'نصب و تعمیر',17,0,99,N'cordless-drill-driver',N'',1),(N'3',N'HN-003',N'dewalt',N'hammer-drills',N'group-1',N'Electric Hammer Drill',N'برق شهری',N'کارگاه ساختمانی',20,0,99,N'electric-hammer-drill',N'',1),(N'4',N'HN-004',N'ronix',N'cordless-drill',N'group-1',N'Two-Speed Cordless Drill Driver',N'باتری شارژی',N'نصب و مونتاژ',23,0,99,N'two-speed-cordless-drill-driver',N'',1),(N'5',N'HN-005',N'tosan',N'hammer-drills',N'group-1',N'Electric Hammer Drill with Keyless Chuck',N'برق شهری',N'تعمیر و نگهداری',26,0,99,N'electric-hammer-drill-with-keyless-chuck',N'',1),(N'6',N'HN-006',N'uni-t',N'digital-multimeters',N'group-2',N'Digital Multimeter',N'باتری‌خور',N'تست و عیب‌یابی',29,15,99,N'digital-multimeter',N'جدید',1),(N'7',N'HN-007',N'fluke',N'digital-multimeters',N'group-2',N'Workshop Digital Multimeter',N'باتری‌خور',N'تعمیرگاه و کارگاه',32,0,99,N'workshop-digital-multimeter',N'',1),(N'8',N'HN-008',N'mastech',N'digital-multimeters',N'group-2',N'Handheld Multimeter with Large Display',N'باتری‌خور',N'تست و عیب‌یابی',35,10,99,N'handheld-multimeter-with-large-display',N'پرفروش',1),(N'9',N'HN-009',N'victor',N'clamp-meters',N'group-2',N'Digital Clamp Meter',N'باتری‌خور',N'برق صنعتی',38,0,99,N'digital-clamp-meter',N'',1),(N'10',N'HN-010',N'kyoritsu',N'digital-multimeters',N'group-2',N'Electrical Installation Digital Multimeter',N'باتری‌خور',N'تأسیسات برقی',41,0,99,N'electrical-installation-digital-multimeter',N'',1),(N'11',N'HN-011',N'yihua',N'soldering-stations',N'group-3',N'Digital Soldering Station',N'برق شهری',N'تعمیر برد',44,15,99,N'digital-soldering-station',N'جدید',1),(N'12',N'HN-012',N'hakko',N'soldering-irons',N'group-3',N'Adjustable Soldering Iron',N'برق شهری',N'مونتاژ الکترونیک',47,0,99,N'adjustable-soldering-iron',N'',1),(N'13',N'HN-013',N'quick',N'hot-air-rework-stations',N'group-3',N'Hot Air Rework Station',N'برق شهری',N'تعمیرات الکترونیک',50,0,99,N'hot-air-rework-station',N'',1),(N'14',N'HN-014',N'weller',N'soldering-stations',N'group-3',N'Bench Soldering Station',N'برق شهری',N'مونتاژ و تعمیر',53,0,99,N'bench-soldering-station',N'',1),(N'15',N'HN-015',N'goot',N'soldering-irons',N'group-3',N'Lightweight Workshop Soldering Iron',N'برق شهری',N'تعمیر برد',56,10,99,N'lightweight-workshop-soldering-iron',N'پرفروش',1),(N'16',N'HN-016',N'philips',N'inspection-lights',N'group-4',N'Portable LED Work Light',N'باتری شارژی',N'بازرسی و تعمیر',14,15,99,N'portable-led-work-light',N'جدید',1),(N'17',N'HN-017',N'arva',N'work-floodlights',N'group-4',N'Workshop LED Floodlight',N'برق شهری',N'کارگاه و نصب',17,0,99,N'workshop-led-floodlight',N'',1),(N'18',N'HN-018',N'ronix',N'inspection-lights',N'group-4',N'Rechargeable Inspection Light',N'باتری شارژی',N'تعمیر خودرو',20,0,99,N'rechargeable-inspection-light',N'',1),(N'19',N'HN-019',N'makita',N'work-floodlights',N'group-4',N'LED Work Light with Stand',N'باتری شارژی',N'نصب و کارگاه',23,0,99,N'led-work-light-with-stand',N'',1),(N'20',N'HN-020',N'dewalt',N'work-floodlights',N'group-4',N'Portable LED Floodlight',N'باتری شارژی',N'محیط کارگاهی',26,0,99,N'portable-led-floodlight',N'',1),(N'21',N'HN-021',N'wiha',N'electrician-hand-tools',N'group-5',N'Insulated Electrician Screwdriver Set',N'دستی',N'نصب و برق‌کاری',29,15,99,N'insulated-electrician-screwdriver-set',N'جدید',1),(N'22',N'HN-022',N'knipex',N'electrician-hand-tools',N'group-5',N'Electrician Pliers Set',N'دستی',N'نصب و تعمیر',32,10,99,N'electrician-pliers-set',N'پرفروش',1),(N'23',N'HN-023',N'stanley',N'electrician-tool-kits',N'group-5',N'Insulated Electrician Tool Kit',N'دستی',N'تعمیر و نگهداری',35,0,99,N'insulated-electrician-tool-kit',N'',1),(N'24',N'HN-024',N'tosan',N'electrician-tool-kits',N'group-5',N'Wiring and Installation Tool Set',N'دستی',N'سیم‌کشی و نصب',38,0,99,N'wiring-and-installation-tool-set',N'',1),(N'25',N'HN-025',N'ronix',N'electrician-tool-kits',N'group-5',N'Electrician Tool Bag Set',N'دستی',N'کارگاه و سرویس',41,0,99,N'electrician-tool-bag-set',N'',1),(N'26',N'HN-026',N'uni-t',N'electrical-testers',N'group-6',N'Digital Voltage Tester',N'باتری‌خور',N'تست اولیه برق',44,15,99,N'digital-voltage-tester',N'جدید',1),(N'27',N'HN-027',N'fluke',N'voltage-testers',N'group-6',N'Non-Contact Voltage Tester',N'باتری‌خور',N'ایمنی و بازرسی',47,0,99,N'non-contact-voltage-tester',N'',1),(N'28',N'HN-028',N'mastech',N'phase-testers',N'group-6',N'Inductive Voltage Tester',N'باتری‌خور',N'تأسیسات برقی',50,0,99,N'inductive-voltage-tester',N'',1),(N'29',N'HN-029',N'benning',N'circuit-testers',N'group-6',N'Circuit Continuity Tester',N'باتری‌خور',N'عیب‌یابی برق',53,10,99,N'circuit-continuity-tester',N'پرفروش',1),(N'30',N'HN-030',N'uni-t',N'voltage-testers',N'group-6',N'Voltage Detector Pen',N'باتری‌خور',N'تست و سرویس',56,0,99,N'voltage-detector-pen',N'',1)) v(StoreProductKey,ProductCode,BrandKey,CategoryKey,DetailKey,EnglishName,PowerSource,UseCase,Price,DiscountPercent,MaxPurchaseQuantity,Slug,Badge,IsNewest) ON v.StoreProductKey=p.StoreProductKey JOIN [Store].[Brand] b ON b.BrandKey=v.BrandKey JOIN [Store].[Category] c ON c.CategoryKey=v.CategoryKey;
