INSERT INTO [Store].[Accessory] ([AccessoryKey],[Name],[Description]) VALUES (N'battery-pack',N'باتری یدک سازگار',N'باتری اضافه برای افزایش زمان کار؛ ولتاژ و نوع اتصال را بررسی کنید.'),(N'solder-tips',N'مجموعه نوک هویه',N'نوک‌های جایگزین؛ قطر و سازگاری با دستهٔ هویه را بررسی کنید.'),(N'worklight-tripod',N'پایهٔ سه‌پایه چراغ کار',N'برای قرارگیری چراغ در ارتفاع؛ نوع اتصال پایه را بررسی کنید.'),(N'driver-bit-set',N'ست سری پیچ‌گوشتی',N'سری‌های پرکاربرد برای باز و بسته‌کردن پیچ‌ها.'),(N'solder-stand-kit',N'پایه و اسفنج تمیزکنندهٔ هویه',N'پایهٔ نگهدارنده و اسفنج نظافت نوک؛ اقلام انتخابی این طرح.'),(N'probe-set',N'ست پراب اندازه‌گیری',N'پراب یدک؛ ردهٔ ایمنی و سازگاری اتصال را بررسی کنید.'),(N'meter-test-lead',N'ست کابل و گیرهٔ تست',N'کابل و گیرهٔ کمکی برای تست‌های کارگاهی؛ ردهٔ ایمنی را با محیط کار تطبیق دهید.'),(N'worklight-battery',N'باتری یدک چراغ کار',N'باتری جایگزین؛ ولتاژ و سازگاری با مدل چراغ را بررسی کنید.'),(N'solder-wire',N'سیم لحیم الکترونیکی',N'سیم لحیم مناسب مونتاژ و تعمیر بردهای الکترونیکی.'),(N'meter-case',N'کیف محافظ مولتی‌متر',N'برای نگهداری دستگاه و پراب‌ها در محیط کار.'),(N'sds-bit-set',N'ست متهٔ چهارشیار بتن',N'مته‌های بتن با اتصال SDS-Plus؛ سازگاری سه‌نظام را بررسی کنید.'),(N'drill-case',N'کیف حمل دریل',N'کیف محافظ برای حمل دریل و متعلقات؛ انتخاب این مورد به طرح فروش بستگی دارد.'),(N'battery-charger-kit',N'باتری و شارژر سازگار',N'پیش از سفارش، سازگاری باتری و شارژر با پلتفرم دستگاه را بررسی کنید.'),(N'shipping-insurance',N'بیمهٔ حمل و تحویل کالا',N'پوشش بیمه‌ای سفارش؛ در این پیشنهاد به‌صورت الزامی محاسبه می‌شود.');
