INSERT INTO [Store].[ProductBenefit] ([IdProduct],[Title],[Detail],[Icon],[SortOrder]) SELECT p.Id,v.Title,v.Detail,v.Icon,v.SortOrder FROM (VALUES (N'1',N'۱۸ ماه ضمانت خدمات فنی',N'از زمان خرید، همراه کالا',N'bi-shield-check',1),(N'1',N'بازرسی سه‌نظام پیش از ارسال',N'کنترل عملکرد بدون هزینهٔ جداگانه',N'bi-wrench-adjustable',2),(N'2',N'۱۲ ماه ضمانت تعمیر',N'پوشش خدمات فنی محصول',N'bi-shield-check',1),(N'3',N'تست ایمنی پیش از ارسال',N'بررسی عملکرد دستگاه در فروشگاه',N'bi-clipboard2-check',1),(N'6',N'کالیبراسیون اولیه',N'آمادهٔ استفاده، بدون هزینهٔ اضافه',N'bi-speedometer2',1),(N'7',N'بررسی دقت اندازه‌گیری',N'کنترل اولیه پیش از تحویل',N'bi-crosshair2',1),(N'11',N'۶ ماه خدمات فنی',N'راهنمایی و بررسی اولیهٔ دستگاه',N'bi-tools',1),(N'16',N'آزمون روشنایی پیش از ارسال',N'کنترل روشن‌شدن و حالت‌های نور',N'bi-lightbulb',1),(N'21',N'بررسی عایق‌بودن ابزار',N'بازبینی اولیه پیش از تحویل',N'bi-shield-check',1),(N'22',N'بازبینی مفصل‌ها و فک انبر',N'کنترل اولیهٔ سلامت ابزار',N'bi-wrench',1)) v(StoreProductKey,Title,Detail,Icon,SortOrder) JOIN [Store].[Product] p ON p.StoreProductKey=v.StoreProductKey;
