INSERT INTO [Store].[FaqItem] ([IdContentPage],[Question],[Answer],[LinkText],[LinkUrl],[SortOrder]) SELECT p.Id,v.Question,v.Answer,v.LinkText,v.LinkUrl,v.SortOrder FROM (VALUES (N'چطور ابزار مناسب انتخاب کنم؟',N'فیلترهای گروه کالا، برند، منبع تغذیه و قیمت را برای محدودکردن گزینه‌ها به‌کار ببرید.',NULL,NULL,1),(N'آیا امکان خرید آنلاین وجود دارد؟',N'در این نسخه پرداخت واقعی فعال نیست؛ برای خرید با فروشگاه تماس بگیرید.',NULL,NULL,2),(N'چگونه سفارش را پیگیری کنم؟',N'تا اتصال سامانهٔ آنلاین، سفارش را از راه پشتیبانی تلفنی پیگیری کنید.',NULL,NULL,3),(N'هزینه و زمان ارسال چقدر است؟',N'مبلغ و زمان تحویل پس از بررسی مقصد و موجودی تأیید می‌شود.',NULL,NULL,4),(N'شرایط ضمانت و مرجوعی چیست؟',N'شرایط ضمانت را در کارت و فاکتور ببینید. راهنمای انصراف و بازگشت کالا در',N'رویه بازگرداندن کالا',N'/legal/returns',5),(N'هزینه و زمان ارسال چگونه مشخص می‌شود؟',N'روش، هزینه و زمان تقریبی پس از بررسی مقصد و موجودی، پیش از تأیید سفارش هماهنگ می‌شود.',NULL,NULL,6),(N'برای پیگیری سفارش چه اطلاعاتی لازم است؟',N'کد سفارش یا فاکتور و شمارهٔ همراه ثبت‌شده را آماده کنید؛ پیگیری آنلاین هنوز به سامانه وصل نیست.',NULL,NULL,7),(N'آیا فهرست علاقه‌مندی‌ها و سبد خرید باقی می‌ماند؟',N'فهرست‌ها در مرورگر ذخیره می‌شوند؛ پاک‌کردن داده‌ها یا تغییر دستگاه ممکن است آن‌ها را حذف کند.',NULL,NULL,8),(N'آیا فرم تماس پیام را برای فروشگاه ارسال می‌کند؟',N'فرم تماس به سامانهٔ پیام متصل نیست. برای پاسخ از راه‌های تماس استفاده کنید.',N'صفحه تماس با ما',N'/contact',9),(N'هنگام دریافت کالا چه مواردی را بررسی کنم؟',N'مدل، تعداد، بسته‌بندی و مدارک را با سفارش تطبیق دهید. برای مغایرت یا آسیب، پیش از ارسال مجدد هماهنگ کنید.',NULL,NULL,10)) v(Question,Answer,LinkText,LinkUrl,SortOrder) CROSS JOIN [Store].[ContentPage] p WHERE p.PageKey=N'faq';
INSERT INTO [Store].[ProductSalesPlanOfferAccessory] ([IdProductSalesPlanOffer],[IdAccessory],[PriceAmount]) SELECT o.Id,a.Id,v.PriceAmount FROM (VALUES (1,N'digi-time',N'shipping-insurance',245000),(1,N'digi-time',N'sds-bit-set',875000),(6,N'digi-time',N'meter-case',455000),(6,N'digi-time',N'probe-set',315000),(11,N'digi-time',N'solder-tips',595000),(11,N'digi-time',N'solder-wire',266000),(1,N'digi-af',N'shipping-insurance',295000),(1,N'digi-af',N'drill-case',820000),(6,N'digi-af',N'meter-case',490000),(6,N'digi-af',N'meter-test-lead',810000),(11,N'digi-af',N'solder-stand-kit',575000),(11,N'digi-af',N'solder-wire',290000)) v(ProductSourceKey,SalesPlanKey,AccessoryKey,PriceAmount) JOIN [Store].[Product] p ON p.StoreProductKey=CONVERT(NVARCHAR(128),v.ProductSourceKey) JOIN [Store].[SalesPlan] sp ON sp.SalesPlanKey=v.SalesPlanKey JOIN [Store].[ProductSalesPlanOffer] o ON o.IdProduct=p.Id AND o.IdSalesPlan=sp.Id JOIN [Store].[Accessory] a ON a.AccessoryKey=v.AccessoryKey;
IF (SELECT COUNT(*) FROM [Store].[Product] WHERE [IdBrand] IS NOT NULL AND [IdCategory] IS NOT NULL AND [PriceAmount] IS NOT NULL)=30 BEGIN DROP INDEX [IX_Store_Product_Brand_Category] ON [Store].[Product]; ALTER TABLE [Store].[Product] ALTER COLUMN [IdBrand] BIGINT NOT NULL; ALTER TABLE [Store].[Product] ALTER COLUMN [IdCategory] BIGINT NOT NULL; ALTER TABLE [Store].[Product] ALTER COLUMN [PriceAmount] DECIMAL(19,0) NOT NULL; CREATE INDEX [IX_Store_Product_Brand_Category] ON [Store].[Product] ([IdBrand], [IdCategory]); END ELSE THROW 51031,'Store catalog fixture did not populate all products.',1;
INSERT INTO [Store].[SchemaMigration] ([MigrationKey]) VALUES (N'004-store-fixture-data');
COMMIT TRANSACTION; END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK TRANSACTION; THROW; END CATCH;